UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Predictable, long-lived, logged or broadly scoped sessions can be stolen or reused.","customer_symptom":"A user or operator may observe predictable, long-lived, logged or broadly scoped sessions can be stolen or reused; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in predictable, long-lived, logged or broadly scoped sessions can be stolen or reused, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["web control planes"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between web control planes and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If predictable, long-lived, logged or broadly scoped sessions can be stolen or reused, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-021 session-token, cookie, login, logout or session-storage change","ARL-KB-021 session lifetime, rotation, revocation or privilege-change behaviour change","ARL-KB-021 fixation, token leakage, session theft or continued-use incident","ARL-KB-021 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='e74238b658c662dcfcb291485d607c458d78a1cdc7a8f626dffffccbe1072114', updated_at='2026-08-06' WHERE id='ARL-KB-021';
UPDATE risk_knowledge_checks SET objective='Determine whether authenticated sessions are unpredictable, protected from disclosure or fixation, bounded in lifetime and invalidated when logout, revocation or privilege changes require it.', method='Test session-token unpredictability, cookie attributes, fixation resistance, rotation after authentication or privilege change, idle and absolute expiry, logout invalidation, concurrent-session handling and accidental disclosure through logs, URLs or client storage.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-021 assessed system, version, environment and scope for Session tokens are weak or mishandled","ARL-KB-021 control configuration or source location showing how reduce the likelihood and impact of session tokens are weak or mishandled and make the remaining risk visible.","ARL-KB-021 positive and abuse inputs with expected and observed outputs for agent and model context","ARL-KB-021 policy, authorization, tool or audit events proving whether the tested session tokens are weak or mishandled path executed","ARL-KB-021 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-021 passes only when “Session tokens are weak or mishandled” is not reproducible through the documented abuse cases, the valid workflow remains bounded to agent and model context, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-021 fails when predictable, long-lived, logged or broadly scoped sessions can be stolen or reused, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-021 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='c741637d2ccd6f599eab4478fa290bc7073f0d8090c184e84b408f05eaccb606', updated_at='2026-08-06' WHERE entry_id='ARL-KB-021';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of session tokens are weak or mishandled and make the remaining risk visible.', recommended_remediation='Use strong opaque tokens, secure cookies, server-side revocation, rotation after privilege change and bounded idle/absolute lifetimes.', default_owner='Application security owner', priority='P1', implementation_principles_json='["ARL-KB-021: Generate high-entropy session identifiers and protect them with secure cookie and transport settings.","ARL-KB-021: Rotate sessions after authentication or privilege changes and enforce bounded idle and absolute lifetimes.","ARL-KB-021: Support server-side revocation and prevent session identifiers from appearing in URLs, logs or other unintended evidence."]', monitoring='For ARL-KB-021, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Application security owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-021 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-021: “Session tokens are weak or mishandled” is no longer reproducible against the exact remediated version.","ARL-KB-021: Authorised in-scope use completes successfully, remains within the documented asset scope for session tokens are weak or mishandled, and produces no unintended side effect.","ARL-KB-021: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-021: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='d26e19af3ab6465b0a5c38a80557ab25d348200c7ecfce077b5fe1b457923eb2', updated_at='2026-08-06' WHERE entry_id='ARL-KB-021';
