UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Password reset or recovery can be abused to take over a high-privilege user.","customer_symptom":"A user or operator may observe password reset or recovery can be abused to take over a high-privilege user; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect can exploit or trigger the condition in password reset or recovery can be abused to take over a high-privilege user, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["backups, runtime state and recovery infrastructure","service availability and data integrity","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["hosted platforms"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between hosted platforms and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If password reset or recovery can be abused to take over a high-privilege user, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-022 recovery, reset, identity-proofing, notification or recovery-code change","ARL-KB-022 privileged-account recovery or MFA-recovery policy change","ARL-KB-022 takeover, enumeration, token-reuse or recovery-bypass incident","ARL-KB-022 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='74b05f86e5e4e96cd27d70c01a22f359758eb2e08bd5d350bb50b8c9b0204ec9', updated_at='2026-08-06' WHERE id='ARL-KB-022';
UPDATE risk_knowledge_checks SET objective='Determine whether account recovery preserves the required authentication assurance and cannot be used to take over a privileged account through enumeration, weak proofing or reusable recovery material.', method='Test account enumeration resistance, recovery-token entropy, expiry and single-use behaviour, identity proofing, notification, recovery-code handling, session invalidation and privileged-account recovery. Verify recovery cannot silently downgrade the normal authentication assurance.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-022 assessed system, version, environment and scope for Account recovery bypasses normal assurance","ARL-KB-022 control configuration or source location showing how reduce the likelihood and impact of account recovery bypasses normal assurance and make the remaining risk visible.","ARL-KB-022 positive and abuse inputs with expected and observed outputs for backups, runtime state and recovery infrastructure and service availability and data integrity","ARL-KB-022 policy, authorization, tool or audit events proving whether the tested account recovery bypasses normal assurance path executed","ARL-KB-022 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-022 passes only when “Account recovery bypasses normal assurance” is not reproducible through the documented abuse cases, the valid workflow remains bounded to backups, runtime state and recovery infrastructure and service availability and data integrity, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-022 fails when password reset or recovery can be abused to take over a high-privilege user, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-022 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='aa4a3b6fe14e8873bc5838df290ba73d7e69d7d92591a0d9472215d1eb7f2ead', updated_at='2026-08-06' WHERE entry_id='ARL-KB-022';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of account recovery bypasses normal assurance and make the remaining risk visible.', recommended_remediation='Harden recovery, rate limit, invalidate sessions after reset, notify the user and require stronger owner recovery procedures.', default_owner='Identity owner', priority='P0', implementation_principles_json='["ARL-KB-022: Recovery must provide assurance appropriate to the account''s privilege and must not become a weaker authentication bypass.","ARL-KB-022: Use high-entropy, short-lived, single-use recovery material and rate-limit recovery attempts.","ARL-KB-022: Notify the account owner and invalidate affected sessions or recovery material after successful reset."]', monitoring='For ARL-KB-022, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Identity owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-022 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-022: “Account recovery bypasses normal assurance” is no longer reproducible against the exact remediated version.","ARL-KB-022: Authorised in-scope use completes successfully, remains within the documented asset scope for account recovery bypasses normal assurance, and produces no unintended side effect.","ARL-KB-022: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-022: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='1344286d22cb3bd89a254c813b6b3135b4087765a69ffc464e99f076603c081e', updated_at='2026-08-06' WHERE entry_id='ARL-KB-022';
