UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Hidden buttons do not stop a low-privilege caller from invoking privileged APIs directly.","customer_symptom":"A user or operator may observe hidden buttons do not stop a low-privilege caller from invoking privileged apis directly; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect can exploit or trigger the condition in hidden buttons do not stop a low-privilege caller from invoking privileged apis directly, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["agent","model context","tools or downstream systems","customer evidence"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["multi-role platforms"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between multi-role platforms and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If hidden buttons do not stop a low-privilege caller from invoking privileged apis directly, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-023 role, permission, route, service-method or authorization-policy change","ARL-KB-023 new privileged function or alternate execution path","ARL-KB-023 function-level authorization bypass or fail-open incident","ARL-KB-023 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='650b26be760c6b40724f15df8ab7e0df57c864b5a90e8123ac94ac673fb31b30', updated_at='2026-08-06' WHERE id='ARL-KB-023';
UPDATE risk_knowledge_checks SET objective='Determine whether the assessed system prevents or detects: role enforcement exists only in the interface.', method='Replay representative privileged requests as each relevant lower-privilege role and through direct API or service calls, including alternate HTTP methods where applicable. Verify authorization is enforced server-side on every sensitive function and fails closed when policy is missing, stale or unavailable.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-023 assessed system, version, environment and scope for Role enforcement exists only in the interface","ARL-KB-023 control configuration or source location showing how reduce the likelihood and impact of role enforcement exists only in the interface and make the remaining risk visible.","ARL-KB-023 positive and abuse inputs with expected and observed outputs for agent and model context","ARL-KB-023 policy, authorization, tool or audit events proving whether the tested role enforcement exists only in the interface path executed","ARL-KB-023 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-023 passes only when “Role enforcement exists only in the interface” is not reproducible through the documented abuse cases, the valid workflow remains bounded to agent and model context, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-023 fails when hidden buttons do not stop a low-privilege caller from invoking privileged apis directly, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-023 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='4a58fa226b2bc0d678dc9185a3fb1f20d9d5c73d6d04967364ea3a8e386ad7ec', updated_at='2026-08-06' WHERE entry_id='ARL-KB-023';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of role enforcement exists only in the interface and make the remaining risk visible.', recommended_remediation='Enforce role and object authorization server-side on every route and service method; maintain negative authorization tests.', default_owner='Application security owner', priority='P0', implementation_principles_json='["ARL-KB-023: Enforce role and function authorization server-side on every sensitive route and service method.","ARL-KB-023: Do not treat hidden interface elements or model behaviour as an authorization boundary.","ARL-KB-023: Maintain negative authorization tests for each privileged function and relevant lower-privilege role."]', monitoring='For ARL-KB-023, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Application security owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-023 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-023: “Role enforcement exists only in the interface” is no longer reproducible against the exact remediated version.","ARL-KB-023: Authorised in-scope use completes successfully, remains within the documented asset scope for role enforcement exists only in the interface, and produces no unintended side effect.","ARL-KB-023: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-023: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='3941ef79385e27943675f67b9e94707542d85e86fd42fbee2b2c76fe5a0e5608', updated_at='2026-08-06' WHERE entry_id='ARL-KB-023';
