UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"A user can read or modify another assessment, project, runtime event, approval or report by changing an identifier.","customer_symptom":"A user or operator may observe a user can read or modify another assessment, project, runtime event, approval or report by changing an identifier; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect can exploit or trigger the condition in a user can read or modify another assessment, project, runtime event, approval or report by changing an identifier, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["multi-user platforms"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between multi-user platforms and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If a user can read or modify another assessment, project, runtime event, approval or report by changing an identifier, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-024 object model, ownership, tenant, workspace, route or authorization-query change","ARL-KB-024 new object read, update, export, delete or indirect access path","ARL-KB-024 cross-user or cross-workspace object-access incident","ARL-KB-024 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='d2596bc1b0593bc6ac5ddc9e017d0163b839812bde2dbf1aae4b24f215e4a4b4', updated_at='2026-08-06' WHERE id='ARL-KB-024';
UPDATE risk_knowledge_checks SET objective='Determine whether object access is authorized against the authenticated principal and tenant or workspace for every read, update, export and delete operation.', method='Using owner-authorised synthetic users and objects, test sequential and random identifiers across users, workspaces and roles for representative read, update, export and delete operations. Verify ownership and tenant scope are resolved server-side rather than trusted from caller-supplied identifiers.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-024 assessed system, version, environment and scope for Object-level authorization can be bypassed","ARL-KB-024 control configuration or source location showing how reduce the likelihood and impact of object-level authorization can be bypassed and make the remaining risk visible.","ARL-KB-024 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-024 policy, authorization, tool or audit events proving whether the tested object-level authorization can be bypassed path executed","ARL-KB-024 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-024 passes only when “Object-level authorization can be bypassed” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tenant-scoped records and object identifiers and service identities, roles and credentials, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-024 fails when a user can read or modify another assessment, project, runtime event, approval or report by changing an identifier, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-024 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='752d83d8f1b2dde74bb8b60e1949a1b726ded04300fc933b7bb39ebe2d2d786c', updated_at='2026-08-06' WHERE entry_id='ARL-KB-024';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of object-level authorization can be bypassed and make the remaining risk visible.', recommended_remediation='Resolve objects through tenant-scoped queries, avoid caller-supplied ownership and deny cross-workspace references consistently.', default_owner='Application security owner', priority='P0', implementation_principles_json='["ARL-KB-024: Resolve objects through server-side principal- and tenant-scoped queries.","ARL-KB-024: Never trust caller-supplied ownership, tenant or workspace identifiers as authorization evidence.","ARL-KB-024: Apply object authorization consistently to read, update, delete, export and indirect service paths."]', monitoring='For ARL-KB-024, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Application security owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-024 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-024: “Object-level authorization can be bypassed” is no longer reproducible against the exact remediated version.","ARL-KB-024: Authorised in-scope use completes successfully, remains within the documented asset scope for object-level authorization can be bypassed, and produces no unintended side effect.","ARL-KB-024: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-024: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='f34b426c1896cd65156f46d218d6ff4555402d9db59b282129b8de51c6ed549e', updated_at='2026-08-06' WHERE entry_id='ARL-KB-024';
