UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"An agent can search, summarise, export or modify another customer''s data even when the web application appears isolated.","customer_symptom":"A user or operator may observe an agent can search, summarise, export or modify another customer''s data even when the web application appears isolated; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in an agent can search, summarise, export or modify another customer''s data even when the web application appears isolated, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","tool endpoints and downstream systems","financial, administrative or state-changing actions"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["multi-tenant agents"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between multi-tenant agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If an agent can search, summarise, export or modify another customer''s data even when the web application appears isolated, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-025 tenant-identity, retrieval, memory, cache, background-job, tool or export-path change","ARL-KB-025 namespace, index, downstream-service or tenant-claim propagation change","ARL-KB-025 cross-tenant access, metadata exposure or isolation-bypass incident","ARL-KB-025 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='197ba5752f39227029c46e7b4bfedeb821b66947bf4213f9e4b33484de7208eb', updated_at='2026-08-06' WHERE id='ARL-KB-025';
UPDATE risk_knowledge_checks SET objective='Determine whether tenant identity is enforced across direct APIs, retrieval, memory, caches, background jobs, tools, exports and logs so one tenant cannot access another tenant''s data or actions.', method='Run cross-tenant tests through direct APIs, vector retrieval, memory, caches, background jobs, tools, exports and logs. Create Tenant A and Tenant B users, roles and object IDs. Attempt direct-ID, list, search, export and tool access across tenants; expect indistinguishable authorization failures and no foreign metadata.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-025 assessed system, version, environment and scope for Tenant isolation fails in retrieval or tools","ARL-KB-025 control configuration or source location showing how reduce the likelihood and impact of tenant isolation fails in retrieval or tools and make the remaining risk visible.","ARL-KB-025 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-025 policy, authorization, tool or audit events proving whether the tested tenant isolation fails in retrieval or tools path executed","ARL-KB-025 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-025 passes only when “Tenant isolation fails in retrieval or tools” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tenant-scoped records and object identifiers and service identities, roles and credentials, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-025 fails when an agent can search, summarise, export or modify another customer''s data even when the web application appears isolated, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-025 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='4137dd5cea8a1f6df05e6d7be6ff7106e137817dd4bf3e8e07993021119cd839', updated_at='2026-08-06' WHERE entry_id='ARL-KB-025';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of tenant isolation fails in retrieval or tools and make the remaining risk visible.', recommended_remediation='Bind tenant identity to every request and data operation, isolate indexes and caches, propagate claims to tools and test every asynchronous path.', default_owner='Security architect', priority='P0', implementation_principles_json='["ARL-KB-025: Bind authoritative tenant identity to every request, retrieval, memory and tool operation.","ARL-KB-025: Isolate indexes, namespaces, caches and asynchronous work by tenant or enforce equivalent server-side policy.","ARL-KB-025: Propagate and revalidate tenant scope across tool calls, exports, background jobs and downstream services."]', monitoring='For ARL-KB-025, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Security architect on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-025 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-025: “Tenant isolation fails in retrieval or tools” is no longer reproducible against the exact remediated version.","ARL-KB-025: Authorised in-scope use completes successfully, remains within the documented asset scope for tenant isolation fails in retrieval or tools, and produces no unintended side effect.","ARL-KB-025: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-025: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='654f0ee0df5cbe052d5c2391fd75aabf59fdd02fe821229fa8600bb8977d6749', updated_at='2026-08-06' WHERE entry_id='ARL-KB-025';
