UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Internal components trust network location or a shared secret, so compromise of one service grants broad access.","customer_symptom":"A user or operator may observe internal components trust network location or a shared secret, so compromise of one service grants broad access; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect can exploit or trigger the condition in internal components trust network location or a shared secret, so compromise of one service grants broad access, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["distributed agents"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between distributed agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If internal components trust network location or a shared secret, so compromise of one service grants broad access, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-026 workload-identity, service, audience, trust-channel or internal-route change","ARL-KB-026 credential lifetime, mutual-authentication or service-policy change","ARL-KB-026 shared-secret exposure, service impersonation or internal identity incident","ARL-KB-026 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='a94e810240ecb11adaeb9ec4bfb757001033a4522785a2529e755f6fc704e259', updated_at='2026-08-06' WHERE id='ARL-KB-026';
UPDATE risk_knowledge_checks SET objective='Determine whether internal services authenticate each other with distinct attributable workload identities and enforce the intended service audience and privilege boundaries.', method='Inspect calls between orchestrator, model gateway, tool gateway, vector store, evidence service and other relevant components for mutual identity, service-specific audience and short-lived credential enforcement. Attempt a synthetic request using an absent, wrong-service or retired workload identity and verify denial.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-026 assessed system, version, environment and scope for Service-to-service identity is unauthenticated or shared","ARL-KB-026 control configuration or source location showing how reduce the likelihood and impact of service-to-service identity is unauthenticated or shared and make the remaining risk visible.","ARL-KB-026 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-026 policy, authorization, tool or audit events proving whether the tested service-to-service identity is unauthenticated or shared path executed","ARL-KB-026 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-026 passes only when “Service-to-service identity is unauthenticated or shared” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tenant-scoped records and object identifiers and service identities, roles and credentials, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-026 fails when internal components trust network location or a shared secret, so compromise of one service grants broad access, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-026 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='109509ea79477cc707b5ee891efd0d623d1298b94dcf318f8a9c5b394cc01954', updated_at='2026-08-06' WHERE entry_id='ARL-KB-026';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of service-to-service identity is unauthenticated or shared and make the remaining risk visible.', recommended_remediation='Use workload identity or mutually authenticated channels, service-specific audiences, short lifetimes and least-privilege policies.', default_owner='Platform identity owner', priority='P1', implementation_principles_json='["ARL-KB-026: Give services distinct workload identities rather than trusting network location or broadly shared secrets.","ARL-KB-026: Bind credentials to the intended service audience and use short lifetimes and least privilege.","ARL-KB-026: Authenticate and authorize every service hop, including internal agent and tool infrastructure."]', monitoring='For ARL-KB-026, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Platform identity owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-026 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-026: “Service-to-service identity is unauthenticated or shared” is no longer reproducible against the exact remediated version.","ARL-KB-026: Authorised in-scope use completes successfully, remains within the documented asset scope for service-to-service identity is unauthenticated or shared, and produces no unintended side effect.","ARL-KB-026: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-026: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='9fe89882ecbce6e4bfdfca511