UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"One leaked key can operate every project, environment or high-impact tool indefinitely.","customer_symptom":"A user or operator may observe one leaked key can operate every project, environment or high-impact tool indefinitely; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in one leaked key can operate every project, environment or high-impact tool indefinitely, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Over-scoped or long-lived API keys can amplify credential compromise. Final severity depends on reachable projects, environments, tools, data, lifetime and revocation controls.","applicability":["API-integrated agents"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between API-integrated agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If one leaked key can operate every project, environment or high-impact tool indefinitely, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due