UPDATE risk_knowledge_checks SET objective='Determine whether human and workload actions requiring accountability are attributable to distinct verified principals.', method='Inspect identity records, privileged account assignments, workload credentials, approval records and audit trails for shared credentials, generic approver identities or ambiguous principals. Verify representative consequential actions can be traced to a distinct human or workload identity.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-029 assessed system, version, environment and scope for Shared accounts destroy accountability","ARL-KB-029 control configuration or source location showing how reduce the likelihood and impact of shared accounts destroy accountability and make the remaining risk visible.","ARL-KB-029 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-029 policy, authorization, tool or audit events proving whether the tested shared accounts destroy accountability path executed","ARL-KB-029 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-029 passes only when “Shared accounts destroy accountability” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tenant-scoped records and object identifiers and service identities, roles and credentials, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-029 fails when multiple people or services act under one identity, making approvals and evidence non-attributable, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-029 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='12c04d29bda15a84bd75daa11b1cdaef6d3b2f27db34ed4ecdf734a748d43783', updated_at='2026-08-06' WHERE entry_id='ARL-KB-029';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of shared accounts destroy accountability and make the remaining risk visible.', recommended_remediation='Provide individual and workload identities, prohibit shared privileged accounts and bind audit records to verified principals.', default_owner='Identity owner', priority='P1', implementation_principles_json='["ARL-KB-029: Provide distinct identities for individual humans and workloads involved in accountable actions.","ARL-KB-029: Prohibit shared privileged credentials except for documented emergency mechanisms with explicit accountability.","ARL-KB-029: Bind approvals, security decisions and audit evidence to verified principals."]', monitoring='For ARL-KB-029, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Identity owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-029 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-029: “Shared accounts destroy accountability” is no longer reproducible against the exact remediated version.","ARL-KB-029: Authorised in-scope use completes successfully, remains within the documented asset scope for shared accounts destroy accountability, and produces no unintended side effect.","ARL-KB-029: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-029: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='9b1068237709ae3833feffe2ca61ad75bfe5d2e770c73785a5b450e86beb866a', updated_at='2026-08-06' WHERE entry_id='ARL-KB-029';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='362e2ab7654c650c056a376271439251642fa5cb70995856a382e737c5276953', updated_at='2026-08-06' WHERE entry_id='ARL-KB-029';
